package com.ehealth.pharmacy.controller;

import com.ehealth.pharmacy.entity.Prescription;
import com.ehealth.pharmacy.repository.PrescriptionRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.UUID;

@RestController
@RequestMapping("/api/health/prescriptions")
public class PrescriptionController {

    private final PrescriptionRepository prescriptionRepository;

    public PrescriptionController(PrescriptionRepository prescriptionRepository) {
        this.prescriptionRepository = prescriptionRepository;
    }

    @PostMapping("/{rxId}/refill")
    public ResponseEntity<String> requestRefill(
            @PathVariable UUID rxId,
            Authentication authentication) {
        Prescription prescription = prescriptionRepository
                .findByIdAndPatientUsername(rxId, authentication.getName())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Prescription not found or does not belong to patient"));
        prescription.setRefillRequested(true);
        prescription.setStatus("PENDING_PHARMACIST_REVIEW");
        prescriptionRepository.save(prescription);
        return ResponseEntity.ok("Refill request submitted successfully");
    }
}
